#include "gui_loader_memory_safe.h"
#include "gui_loader.h"
#include <string.h>

// Include the TFT header for the class definition
// We'll use a forward declaration approach instead

// ============================================================================
// Memory-Safe Loading Implementation
// ============================================================================

void* gui_loader_load_with_memory_check(const char* json, TFT_ST7789* tft) {
    #if GUI_LOADER_MEMORY_CHECK_ENABLED
    
    if (!json) {
        if (tft) {
            gui_memory_display_oom_error(tft, "Invalid JSON");
        }
        return NULL;
    }
    
    // Check memory requirements
    GuiMemoryStats stats = gui_memory_calculate_from_json(json);
    
    if (!stats.fits_in_memory) {
        // Display error on TFT
        if (tft) {
            gui_memory_display_error(tft, &stats);
        }
        return NULL;
    }
    
    // Memory is OK, proceed with loading
    return gui_loader_parse_json(json);
    
    #else
    // Memory checking disabled, load directly
    return gui_loader_parse_json(json);
    #endif
}

void* gui_loader_load_file_with_memory_check(const char* filepath, TFT_ST7789* tft) {
    #if GUI_LOADER_MEMORY_CHECK_ENABLED
    
    if (!filepath) {
        if (tft) {
            gui_memory_display_oom_error(tft, "Invalid file path");
        }
        return NULL;
    }
    
    // Check file size first
    int file_size = gui_loader_get_size(filepath);
    if (file_size < 0 || file_size > GUI_LOADER_MAX_FILE_SIZE) {
        if (tft) {
            gui_memory_display_oom_error(tft, "File too large or not found");
        }
        return NULL;
    }
    
    // Check memory requirements
    GuiMemoryStats stats = gui_memory_calculate_from_file(filepath);
    
    if (!stats.fits_in_memory) {
        // Display error on TFT
        if (tft) {
            gui_memory_display_error(tft, &stats);
        }
        return NULL;
    }
    
    // Memory is OK, proceed with loading
    return gui_loader_parse_json(NULL); // Placeholder - actual implementation would parse file
    
    #else
    // Memory checking disabled, load directly
    return gui_loader_parse_json(NULL); // Would load from file
    #endif
}

void* gui_loader_load_sd_with_memory_check(const char* filename, TFT_ST7789* tft) {
    #if GUI_LOADER_MEMORY_CHECK_ENABLED
    
    if (!filename) {
        if (tft) {
            gui_memory_display_oom_error(tft, "Invalid filename");
        }
        return NULL;
    }
    
    // Build full path
    char filepath[128];
    snprintf(filepath, sizeof(filepath), "/gui/%s", filename);
    
    // Check file size
    int file_size = gui_loader_get_size(filepath);
    if (file_size < 0 || file_size > GUI_LOADER_MAX_FILE_SIZE) {
        if (tft) {
            char error_msg[64];
            snprintf(error_msg, sizeof(error_msg), "File not found: %s", filename);
            gui_memory_display_oom_error(tft, error_msg);
        }
        return NULL;
    }
    
    // Check memory requirements
    GuiMemoryStats stats = gui_memory_calculate_from_file(filepath);
    
    if (!stats.fits_in_memory) {
        // Display error on TFT
        if (tft) {
            gui_memory_display_error(tft, &stats);
        }
        return NULL;
    }
    
    // Memory is OK, load from SD
    return gui_loader_load_from_sd(filename);
    
    #else
    // Memory checking disabled, load directly
    return gui_loader_load_from_sd(filename);
    #endif
}

void* gui_loader_load_webdav_with_memory_check(const char* filename, TFT_ST7789* tft) {
    #if GUI_LOADER_MEMORY_CHECK_ENABLED
    
    if (!filename) {
        if (tft) {
            gui_memory_display_oom_error(tft, "Invalid filename");
        }
        return NULL;
    }
    
    // First load the file from WebDAV to a buffer
    char buffer[GUI_LOADER_MAX_FILE_SIZE + 1];
    int bytes_read = gui_loader_load_from_webdav(filename, buffer, GUI_LOADER_MAX_FILE_SIZE);
    
    if (bytes_read <= 0) {
        if (tft) {
            char error_msg[64];
            snprintf(error_msg, sizeof(error_msg), "Cannot load: %s", filename);
            gui_memory_display_oom_error(tft, error_msg);
        }
        return NULL;
    }
    
    buffer[bytes_read] = '\0';
    
    // Check memory requirements
    GuiMemoryStats stats = gui_memory_calculate_from_json(buffer);
    
    if (!stats.fits_in_memory) {
        // Display error on TFT
        if (tft) {
            gui_memory_display_error(tft, &stats);
        }
        return NULL;
    }
    
    // Memory is OK, parse the JSON
    return gui_loader_parse_json(buffer);
    
    #else
    // Memory checking disabled, load directly
    return gui_loader_parse_json(NULL); // Would load from WebDAV
    #endif
}

// ============================================================================
// GUI Memory Information Functions
// ============================================================================

GuiMemoryStats gui_loader_get_memory_info(const char* json) {
    return gui_memory_calculate_from_json(json);
}

GuiMemoryStats gui_loader_get_memory_info_file(const char* filepath) {
    return gui_memory_calculate_from_file(filepath);
}

bool gui_loader_has_enough_memory(const char* json) {
    GuiMemoryStats stats = gui_memory_calculate_from_json(json);
    return stats.fits_in_memory;
}

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Get required memory for a GUI before loading
 * Useful for pre-checking before actual loading
 * 
 * @param json_or_file Either a JSON string or file path (detects based on first char)
 * @param is_file true if input is a file path, false if JSON string
 * @return GuiMemoryStats with memory information
 */
GuiMemoryStats gui_loader_get_required_memory(const char* json_or_file, bool is_file) {
    if (is_file) {
        return gui_loader_get_memory_info_file(json_or_file);
    } else {
        return gui_loader_get_memory_info(json_or_file);
    }
}

/**
 * Pre-check multiple GUI files for memory requirements
 * Useful for GUI selection/management
 * 
 * @param files Array of file paths
 * @param count Number of files
 * @param results Array to store results (must be pre-allocated)
 * @return Number of files that fit in memory
 */
int gui_loader_precheck_files(const char** files, int count, bool* results) {
    if (!files || !results || count <= 0) return 0;
    
    int fit_count = 0;
    for (int i = 0; i < count; i++) {
        GuiMemoryStats stats = gui_loader_get_memory_info_file(files[i]);
        results[i] = stats.fits_in_memory;
        if (results[i]) fit_count++;
    }
    
    return fit_count;
}
